"use client"

import * as React from "react"
import { PauseIcon, PlayIcon, Volume2Icon, VolumeXIcon } from "lucide-react"
import { cn } from "cn"

import { Button } from "@/components/ui/button"
import { Slider } from "@/components/ui/slider"

function formatTime(seconds: number) {
  if (!Number.isFinite(seconds)) return "0:00"
  const s = Math.floor(seconds % 60)
  const m = Math.floor(seconds / 60) % 60
  const h = Math.floor(seconds / 3600)
  const mm = h ? String(m).padStart(2, "0") : String(m)
  return `${h ? `${h}:` : ""}${mm}:${String(s).padStart(2, "0")}`
}

/**
 * Native <video>/<audio> with an aria-nova control bar: React Aria Button for
 * play and mute, React Aria Slider for seek and volume. controls.full shows
 * seek, time and volume; controls.minimal shows play and seek only.
 */
function MediaPlayer({
  src,
  kind = "video",
  poster,
  title,
  controls = "full",
  className,
}: {
  src: string
  kind?: "video" | "audio"
  poster?: string
  title: string
  controls?: "full" | "minimal"
  className?: string
}) {
  const ref = React.useRef<HTMLVideoElement & HTMLAudioElement>(null)
  const [playing, setPlaying] = React.useState(false)
  const [time, setTime] = React.useState(0)
  const [duration, setDuration] = React.useState(0)
  const [volume, setVolume] = React.useState(1)
  const [muted, setMuted] = React.useState(false)

  const toggle = () => {
    const el = ref.current
    if (!el) return
    if (el.paused) void el.play()
    else el.pause()
  }
  const media = {
    ref,
    src,
    preload: "metadata" as const,
    onPlay: () => setPlaying(true),
    onPause: () => setPlaying(false),
    onTimeUpdate: () => setTime(ref.current?.currentTime ?? 0),
    onLoadedMetadata: () => setDuration(ref.current?.duration ?? 0),
    onVolumeChange: () => {
      setVolume(ref.current?.volume ?? 1)
      setMuted(ref.current?.muted ?? false)
    },
  }

  return (
    <figure
      data-slot="media-player"
      data-controls={controls}
      className={cn("relative flex w-full flex-col overflow-hidden rounded-lg border border-border bg-muted", className)}
    >
      {kind === "video" ? (
        <video {...media} poster={poster} playsInline onClick={toggle} className="aspect-video w-full bg-foreground/5 object-cover" />
      ) : (
        <audio {...media} />
      )}
      <figcaption className="sr-only">{title}</figcaption>
      <div className="flex items-center gap-2 border-t border-border bg-background px-2 py-1.5">
        <Button variant="ghost" size="icon-sm" aria-label={playing ? `Pause ${title}` : `Play ${title}`} onPress={toggle}>
          {playing ? <PauseIcon /> : <PlayIcon />}
        </Button>
        <Slider
          aria-label="Seek"
          minValue={0}
          maxValue={duration || 1}
          step={0.1}
          value={time}
          onChange={(v) => {
            if (ref.current) ref.current.currentTime = v
          }}
          className="flex-1"
        />
        {controls === "full" && (
          <>
            <span className="text-xs text-muted-foreground tabular-nums">
              {formatTime(time)} / {formatTime(duration)}
            </span>
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={muted ? "Unmute" : "Mute"}
              onPress={() => {
                if (ref.current) ref.current.muted = !ref.current.muted
              }}
            >
              {muted || volume === 0 ? <VolumeXIcon /> : <Volume2Icon />}
            </Button>
            <Slider
              aria-label="Volume"
              minValue={0}
              maxValue={1}
              step={0.05}
              value={muted ? 0 : volume}
              onChange={(v) => {
                if (!ref.current) return
                ref.current.volume = v
                ref.current.muted = v === 0
              }}
              className="hidden w-20 sm:flex"
            />
          </>
        )}
      </div>
    </figure>
  )
}

export { MediaPlayer }
